        FirstName = "FirstName",
        LastName = "LastName",
        TradingName = "John's Super Hero Masks",
        RegisteredAddress = new Address
        {
            AddressLine1 = "123 High St.",
            AddressLine2 = "Flat 456",
            City = "London",
            State = "GB",
            Zip = "SW1A 1AA",
            Country = CountryCode.GB
